const EXV={"Tirage vertical":["Prise",[["Large","Tirage vertical"],["Serrée","Tirage vertical prise serrée"],["Inversée","Tirage vertical prise inversée"],["Neutre","Tirage vertical prise neutre"]]],"Extension poulie":["Poignée",[["Barre","Extension poulie"],["Corde","Extension poulie corde"],["Barre en V","Extension poulie barre en V"],["Inversée","Extension poulie prise inversée"]]],"Tractions":["Prise",[["Normale","Tractions"],["Inversée","Tractions supination"]]],"Rowing barre":["Prise",[["Normale","Rowing barre"],["Inversée","Rowing barre prise inversée"]]],"Curl barre":["Prise",[["Normale","Curl barre"],["Inversée","Curl inversé barre"]]],"Développé couché":["Prise",[["Normale","Développé couché"],["Large","Développé couché prise large"]]],"Développé couché haltères":["Prise",[["Normale","Développé couché haltères"],["Neutre","Développé couché haltères prise neutre"]]]};
